#!/usr/bin/env node
// Pri Learning · public site contract (site/)
//
//   node tools/site-check.mjs          check the committed site/public
//   node tools/site-check.test.mjs     prove each rule catches a planted regression
//
// prilearning.com is static HTML generated by site/build.mjs from docs/legal
// and site/src. This suite holds it to four promises:
//
//   1. It cannot drift from the notices. site/public must equal a fresh render,
//      so a change to docs/legal that is not re-generated fails CI, and no
//      page may carry a {{PLACEHOLDER}}.
//   2. It says only what is approved. The site's own copy — everything outside
//      the <article data-source="docs/legal/…"> bodies, which docs/legal and
//      client/test/legal-pages-check.mjs govern — may not use the words the
//      V1 coverage decision bans (audit-content; V1_DECISIONS D24): nothing
//      about a syllabus being whole, accuracy, question counts, percentiles,
//      working without a connection, examiners, store badges, or any price
//      except the two approved ones. Required sentences must be present.
//   3. Nothing is broken and nothing phones home. Every internal link and
//      fragment resolves inside the output, every external link is on the
//      allowlist and HTTPS, and no script, style, image, font, frame or form
//      reaches another origin. No analytics.
//   4. The Vercel config stays a static deployment: clean URLs, no build, no
//      functions, no environment, security headers, redirects that resolve.
//
// checkSite() is pure so the self-test can mutate a rendered copy in memory.

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { diffOutput, readOutput, renderSite } from '../site/build.mjs';
import { APP_ORIGIN, PRICES, SITE_ORIGIN } from '../site/src/config.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

// ── Vocabulary ───────────────────────────────────────────────────────────────

export const BANNED = [
  // Coverage and quality claims (D24 "never use")
  [/\bcomplete(d|ly|ness)?\b/i, 'claims completeness'],
  [/\b(full|entire|whole|complete) syllabus\b/i, 'claims the whole syllabus'],
  [/\bsyllabus[- ]complete\b/i, 'claims the whole syllabus'],
  [/\bevery (chapter|topic|question|dot[- ]point)\b/i, 'claims every chapter or topic'],
  [/\ball of it\b/i, 'claims all of it'],
  [/\bcomprehensive\b/i, 'claims comprehensiveness'],
  [/\bcertif(ied|ication|icate)\b/i, 'claims certification'],
  [/\bofficial(ly)?\b/i, 'claims an official status'],
  [/\baccura(te|cy|tely)\b/i, 'claims accuracy'],
  [/\bexaminer/i, 'invokes an examiner'],
  [/\bhardest\b/i, 'claims the hardest'],
  [/\bsyllabus[- ]aligned\b|\baligned (to|with) the syllabus\b/i, 'claims syllabus alignment'],
  [/\bunlimited\b/i, 'claims unlimited'],
  [/\boffline\b/i, 'describes working without a connection'],
  [/\bpercentile\b/i, 'mentions a percentile'],
  [/\brank predict|\bmark predict|\bpredicted (rank|mark|percentile)/i, 'predicts a rank or mark'],
  [/\bguarantee/i, 'guarantees something'],
  [/\b(method|step) marks?\b/i, 'promises method marks, which are off in V1'],
  [/\d+(\.\d+)?\s?%/, 'states a percentage'],
  [/\b\d{1,3}(,\d{3})+\+?\s+(distinct\s+)?questions?\b/i, 'states a question count'],
  [/\b\d{4,}\+?\s+(distinct\s+)?questions?\b/i, 'states a question count'],
  [/\b(over|more than|thousands of|lakhs? of|crores? of)\s+(\d[\d,]*\s+)?questions\b/i, 'states a question count'],
  // Superiority and hype (AGENTS.md)
  [/\b#1\b|\bnumber one\b|\bthe best\b|\bbetter than\b|\bbeats?\b|\boutperform/i, 'claims superiority'],
  [/\btrusted by\b|\bloved by\b|\bworld[- ]class\b|\bproduction[- ]ready\b/i, 'unsupported claim'],
  [/\bAI[- ]powered\b|\bpowered by AI\b|\bsmart AI\b/i, 'sells AI as the marker'],
  [/\bsparkl|✨|[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u, 'sparkles or emoji'],
  // Store state (not on sale; no badges)
  [/download (it )?(on|from) the app store|get it on google play|download now|available now|out now|install now/i, 'implies the app is on sale'],
  [/apps\.apple\.com|play\.google\.com/i, 'links a store page before the app is on sale'],
  // Out of V1 (audit-scope, D1–D4, D23)
  [/\bOlympiad\b|\bRazorpay\b|\bAI tutor\b|\bpast[- ]paper/i, 'describes something outside V1'],
  // Hindi equivalents of the same bans
  [/पूरा पाठ्यक्रम|संपूर्ण पाठ्यक्रम|पूरे पाठ्यक्रम/u, 'claims the whole syllabus (Hindi)'],
  [/हर अध्याय|हर विषय|सभी अध्याय/u, 'claims every chapter (Hindi)'],
  [/ऑफ़लाइन|ऑफलाइन/u, 'describes working without a connection (Hindi)'],
  [/सटीक|प्रमाणित|आधिकारिक|परीक्षक|असीमित|प्रतिशत|गारंटी|सबसे कठिन/u, 'banned claim (Hindi)']
];

// Every ₹ amount on the site must be one of these, verbatim (D19).
export const APPROVED_PRICES = new Set(Object.values(PRICES));

export const REQUIRED = {
  'index.html': [
    'Marking is automatic and can be wrong',
    'Not endorsed by NCERT, CBSE or NTA',
    /coming soon/i,
    'fixed set of mathematical rules',
    'never by an AI model',
    PRICES.monthly,
    PRICES.annual,
    'App Store',
    'CBSE / NCERT Classes 7 to 12, JEE Main and JEE Advanced'
  ],
  'support/index.html': ['id="grievance"', 'mailto:', 'Marking is automatic and can be wrong'],
  'hi/support/index.html': ['id="grievance"', 'mailto:'],
  'delete-account/index.html': ['immediate', `${APP_ORIGIN}/account/delete-request`],
  'hi/delete-account/index.html': [`${APP_ORIGIN}/account/delete-request`]
};

export const ALLOWED_EXTERNAL_HOSTS = new Set([new URL(APP_ORIGIN).host]);

const TRACKING = /googletagmanager|google-analytics|gtag\(|analytics\.js|fbq\(|facebook\.net|hotjar|mixpanel|segment\.(io|com)|posthog|plausible\.io|clarity\.ms|amplitude|sentry\.io|doubleclick|matomo/i;

// ── Helpers ──────────────────────────────────────────────────────────────────

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
export const decode = (s) => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&([a-z]+);/gi, (m, n) => ENTITIES[n.toLowerCase()] ?? m);

const LEGAL_ARTICLE = /<article[^>]*\bdata-source="docs\/legal\/[^"]+"[^>]*>[\s\S]*?<\/article>/g;

/** The words the site itself says: tags stripped, legal bodies removed, plus the attributes a reader meets. */
export function authoredText(html) {
  const withoutLegal = String(html).replace(LEGAL_ARTICLE, ' ');
  const attrs = [...withoutLegal.matchAll(/\b(?:content|alt|title|aria-label|placeholder)="([^"]*)"/g)].map(m => m[1]);
  const text = withoutLegal
    .replace(/<script[\s\S]*?<\/script>/g, ' ')
    .replace(/<style[\s\S]*?<\/style>/g, ' ')
    .replace(/<[^>]+>/g, ' ');
  return decode([text, ...attrs].join(' ')).replace(/\s+/g, ' ');
}

/** href/src/srcset targets in an HTML document, with the tag they sit on. */
export function linksIn(html) {
  const out = [];
  for (const m of String(html).matchAll(/<([a-z][a-z0-9-]*)\b[^>]*?\s(href|src|srcset|action|poster|data)="([^"]*)"/gi)) {
    out.push({ tag: m[1].toLowerCase(), attr: m[2].toLowerCase(), value: decode(m[3]) });
  }
  return out;
}

/** The output file a root-relative route is served from, or null. */
export function resolveRoute(route, files) {
  const clean = route.replace(/[?#].*$/, '');
  if (clean === '/' || clean === '') return 'index.html';
  const path = clean.replace(/^\//, '');
  if (files.has(`${path}/index.html`)) return `${path}/index.html`;
  if (files.has(path)) return path;
  return null;
}

const idsIn = (html) => new Set([...String(html).matchAll(/\sid="([^"]+)"/g)].map(m => m[1]));

// ── The check ────────────────────────────────────────────────────────────────

/**
 * @param {Map<string,string>} rendered   fresh render from site/build.mjs
 * @param {Map<string,string>} committed  what is in site/public
 * @param {object|null}        vercel     parsed site/vercel.json
 * @returns {{ failures: string[], checks: number }}
 */
export function checkSite({ rendered, committed, vercel }) {
  const failures = [];
  let checks = 0;
  const fail = (msg) => failures.push(msg);
  const ok = (cond, msg) => { checks++; if (!cond) fail(msg); };

  // 1. Freshness and placeholders
  for (const line of diffOutput(rendered, committed)) fail(`stale: ${line}`);
  checks++;
  for (const [path, body] of committed) {
    ok(!/\{\{[A-Z_]+\}\}/.test(body), `${path}: carries an unfilled {{PLACEHOLDER}}`);
  }

  const html = [...committed].filter(([p]) => p.endsWith('.html'));
  ok(html.length >= 12, `expected at least 12 HTML pages, found ${html.length}`);

  for (const [path, body] of html) {
    const lang = body.match(/<html lang="([a-z]{2})"/)?.[1];
    // 2. Structure
    ok(lang === 'en' || lang === 'hi', `${path}: <html lang> must be en or hi`);
    ok(/<title>[^<]+<\/title>/.test(body), `${path}: has a <title>`);
    ok(/<meta name="viewport"/.test(body), `${path}: has a viewport meta`);
    ok(/<meta name="description" content="[^"]{20,}"/.test(body), `${path}: has a meta description`);
    ok((body.match(/<h1[\s>]/g) || []).length === 1, `${path}: exactly one <h1>`);
    ok(/<main id="main"/.test(body), `${path}: has <main id="main">`);
    ok(/<meta name="color-scheme" content="light dark">/.test(body), `${path}: declares light and dark`);
    const notices = lang === 'hi' ? ['/hi/privacy', '/hi/terms'] : ['/privacy', '/terms'];
    for (const n of notices) ok(body.includes(`href="${n}"`), `${path}: links ${n}`);
    ok(/can be wrong|गलत हो सकती है/.test(body), `${path}: says marking can be wrong`);
    ok(/not endorsed by|समर्थन, अनुमोदन या संबद्धता प्राप्त नहीं/i.test(body), `${path}: says it is not endorsed`);

    // 3a. Nothing phones home
    ok(!TRACKING.test(body), `${path}: contains an analytics or tracking reference`);
    ok(!/<(iframe|form|input|textarea|select|object|embed)\b/i.test(body), `${path}: contains a frame or a form; the site collects nothing`);
    ok(!/<script\b(?![^>]*\bsrc="\/theme\.js")[^>]*>/i.test(body), `${path}: contains a script other than /theme.js`);
    ok(!/@import|url\(\s*["']?https?:/i.test(body), `${path}: inline CSS loads a remote asset`);
    ok(!/<img\b/i.test(body), `${path}: contains an <img>; the site uses typeset maths and inline SVG only (no screenshots, no store badges)`);

    // 3b. Words
    const text = authoredText(body);
    for (const [pattern, why] of BANNED) {
      const m = pattern.exec(text);
      ok(!m, `${path}: banned phrase — ${why}: "${m?.[0]}"`);
    }
    for (const m of text.matchAll(/₹\s?[\d,]+(\.\d+)?/g)) {
      ok(APPROVED_PRICES.has(m[0]), `${path}: price "${m[0]}" is not one of the approved prices (${[...APPROVED_PRICES].join(', ')})`);
    }
    for (const needle of REQUIRED[path] || []) {
      const present = needle instanceof RegExp ? needle.test(body) : body.includes(needle);
      ok(present, `${path}: required text missing — ${needle}`);
    }

    // 3c. Links
    for (const { tag, attr, value } of linksIn(body)) {
      if (value.startsWith('mailto:')) { ok(/^mailto:[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(value), `${path}: malformed ${value}`); continue; }
      if (value.startsWith('#')) { ok(idsIn(body).has(value.slice(1)), `${path}: broken fragment ${value}`); continue; }
      let target = value;
      if (target.startsWith(SITE_ORIGIN + '/') || target === SITE_ORIGIN) target = target.slice(SITE_ORIGIN.length) || '/';
      if (/^[a-z][a-z0-9+.-]*:/i.test(target)) {
        let url;
        try { url = new URL(target); } catch { fail(`${path}: unparseable URL ${value}`); continue; }
        ok(url.protocol === 'https:', `${path}: non-HTTPS link ${value}`);
        ok(ALLOWED_EXTERNAL_HOSTS.has(url.host), `${path}: external link to ${url.host} is not on the allowlist`);
        ok(!['script', 'link', 'img', 'iframe', 'source', 'video', 'audio', 'object', 'embed'].includes(tag), `${path}: <${tag}> loads ${value} from another origin`);
        continue;
      }
      ok(target.startsWith('/'), `${path}: ${attr} "${value}" must be root-relative`);
      ok(!/\/(\?|#|$)/.test(target) || target === '/' || target.startsWith('/#'), `${path}: "${value}" has a trailing slash, which Vercel redirects`);
      const [route, fragment] = target.split('#');
      const file = resolveRoute(route, committed);
      ok(file, `${path}: broken internal link ${value}`);
      if (file && fragment) ok(idsIn(committed.get(file)).has(fragment), `${path}: ${value} points at an id that does not exist`);
    }
  }

  // Stylesheet and script load nothing remote
  const css = committed.get('styles.css') || '';
  ok(!/@import|url\(\s*["']?https?:/i.test(css), 'styles.css loads a remote asset');
  ok(!/https?:\/\//i.test(committed.get('theme.js') || ''), 'theme.js reaches a URL');
  ok(/prefers-color-scheme: dark/.test(css) && /\[data-theme="dark"\]/.test(css) && /\[data-theme="light"\]/.test(css), 'styles.css carries both themes and the override');
  ok(/prefers-reduced-motion/.test(css), 'styles.css honours reduced motion');
  ok((css.match(/radial-gradient/g) || []).length === 1, 'exactly one glow on the site');

  // Sitemap and robots
  const sitemap = committed.get('sitemap.xml') || '';
  for (const m of sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)) {
    const route = m[1].replace(SITE_ORIGIN, '') || '/';
    ok(resolveRoute(route, committed), `sitemap.xml: ${m[1]} does not resolve`);
  }
  ok(/Sitemap: /.test(committed.get('robots.txt') || ''), 'robots.txt names the sitemap');
  ok(committed.has('404.html'), '404.html exists for Vercel');

  // 4. Vercel stays static
  ok(vercel && typeof vercel === 'object', 'site/vercel.json parses');
  if (vercel && typeof vercel === 'object') {
    ok(vercel.cleanUrls === true, 'vercel.json: cleanUrls must be true');
    ok(vercel.trailingSlash === false, 'vercel.json: trailingSlash must be false');
    ok(vercel.framework === null, 'vercel.json: framework must be null (no build)');
    ok(vercel.buildCommand === null && vercel.installCommand === null, 'vercel.json: no build or install command');
    for (const key of ['functions', 'builds', 'env', 'build', 'crons', 'rewrites']) ok(!(key in vercel), `vercel.json: "${key}" is not allowed on the static site`);
    const headers = (vercel.headers || []).flatMap(h => h.headers || []);
    const csp = headers.find(h => /^content-security-policy$/i.test(h.key))?.value || '';
    ok(/default-src 'none'/.test(csp) && /script-src 'self'/.test(csp) && /frame-ancestors 'none'/.test(csp), 'vercel.json: CSP locks the page down');
    ok(!/connect-src/.test(csp), 'vercel.json: CSP allows no connections');
    ok(headers.some(h => /^referrer-policy$/i.test(h.key)), 'vercel.json: Referrer-Policy set');
    for (const r of vercel.redirects || []) {
      ok(resolveRoute(r.destination, committed), `vercel.json: redirect ${r.source} → ${r.destination} does not resolve`);
      ok(!resolveRoute(r.source, committed), `vercel.json: redirect source ${r.source} shadows a real page`);
      if (r.destination.includes('#')) ok(idsIn(committed.get(resolveRoute(r.destination, committed)) || '').has(r.destination.split('#')[1]), `vercel.json: redirect ${r.destination} fragment missing`);
    }
  }

  return { failures, checks };
}

export function loadVercel() {
  try { return JSON.parse(readFileSync(join(ROOT, 'site/vercel.json'), 'utf8')); } catch { return null; }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const rendered = renderSite();
  const committed = readOutput();
  const { failures, checks } = checkSite({ rendered, committed, vercel: loadVercel() });
  if (failures.length) {
    console.error(`SITE: FAIL — ${failures.length} of ${checks} checks`);
    for (const f of failures) console.error(`  ✗ ${f}`);
    process.exit(1);
  }
  console.log(`SITE: PASS — ${checks}/${checks} checks across ${committed.size} files (${[...committed.keys()].filter(p => p.endsWith('.html')).length} pages, ${BANNED.length} banned patterns, ${APPROVED_PRICES.size} approved prices)`);
}
